// function safeGet(arr, index) mein array aur index do
// Agar array nahi: undefined
// Agar index out of bounds: undefined
// Warna element return karo

solution:
function safeGet(arr, index) {
  if (!Array.isArray(arr)) return undefined
  if (index < 0 || index >= arr.length) return undefined
  return arr[index]
}
